SELECT result FROM ( SELECT si.item_name || '~' || si.sale_price AS result FROM shop_items si WHERE si.room_id = '917446ff80d14cacf75b035961cc89303d3d51e9' AND si.sale_price NOT IN ('found','loot','') UNION SELECT ni.item_name || '~' || ni.sale_price AS result FROM npc_items ni JOIN npc_info n ON n.npc_id = ni.npc_id WHERE n.room_id = '917446ff80d14cacf75b035961cc89303d3d51e9' AND ni.sale_price NOT IN ('found','loot','') ) ORDER BY result LIMIT 61;